"""Run from the folder containing pyproject.toml:  python fix_strict.py
Adds `abuselens evaluate --strict` (host-disjoint test with a freshly trained model)."""
from pathlib import Path

root = Path.cwd()
if not (root / "pyproject.toml").exists():
    raise SystemExit("Run this from the folder that contains pyproject.toml")
FILES = [
    ('src/abuselens/models/evaluate.py', '"""Honest breakdown of the champion model on its held-out test slice, by abuse type."""\nfrom __future__ import annotations\n\nimport numpy as np\nimport pandas as pd\n\nfrom . import metrics, train\n\n\ndef by_type(bundle: dict, test: pd.DataFrame) -> pd.DataFrame:\n    """Recall per malicious type at the frozen threshold, plus FPR on safe URLs, plus\n    ROC-AUC / PR-AUC of each type against the same safe URLs."""\n    s = train.score(bundle, test)\n    t = test.assign(score=s)\n    safe = t[t.label == 0]\n    rows = [{"slice": "safe (false positives)", "n": len(safe),\n             "flagged_rate": float((safe.score >= bundle["threshold"]).mean()),\n             "roc_auc": np.nan, "pr_auc": np.nan}]\n    for typ, g in t[t.label == 1].groupby("abuse_type"):\n        both = pd.concat([g, safe])\n        m = metrics.evaluate(both.label, both.score, bundle["threshold"], train.ASSUMED_PREVALENCE)\n        rows.append({"slice": typ, "n": len(g), "flagged_rate": float((g.score >= bundle["threshold"]).mean()),\n                     "roc_auc": m["roc_auc"], "pr_auc": m["pr_auc"]})\n    return pd.DataFrame(rows)\n\n\ndef importances(bundle: dict, k: int = 12) -> pd.DataFrame:\n    b = bundle["model"].get_booster()\n    gain = b.get_score(importance_type="total_gain")\n    out = pd.DataFrame({"feature": list(gain), "gain": list(gain.values())})\n    out["share"] = out.gain / out.gain.sum()\n    return out.sort_values("share", ascending=False).head(k).reset_index(drop=True)\n\n\ndef host_split(df: pd.DataFrame, test_frac: float = 0.25, val_frac: float = 0.15, seed: int = 7):\n    """Strict split: all URLs of a host go to exactly one of train / calibration / test.\n\n    Done per (label, abuse type) so each group appears in every part. This removes the\n    near-duplicate leakage of phishing kits and malware servers that reuse one host, so the\n    test measures detection on hosts the model has never seen.\n    """\n    rng = np.random.default_rng(seed)\n    parts = {0: [], 1: [], 2: []}\n    for _, g in df.groupby(["label", "abuse_type"]):\n        counts = g.groupby("host").size()\n        hosts = counts.index.to_numpy()\n        rng.shuffle(hosts)\n        share = counts.loc[hosts].cumsum().to_numpy() / len(g)\n        cut_test, cut_val = 1 - test_frac, (1 - test_frac) * (1 - val_frac)\n        which = np.where(share <= cut_val, 0, np.where(share <= cut_test, 1, 2))\n        # never leave a part empty for small groups\n        for k in (0, 1, 2):\n            if not (which == k).any():\n                which[min(k, len(which) - 1)] = k\n        assign = dict(zip(hosts, which, strict=True))\n        m = g["host"].map(assign)\n        for k in (0, 1, 2):\n            parts[k].append(g[m == k])\n    return tuple(pd.concat(parts[k]).reset_index(drop=True) for k in (0, 1, 2))\n\n\ndef strict_report(df: pd.DataFrame) -> tuple[pd.DataFrame, pd.DataFrame, dict]:\n    """Train a fresh model on host-disjoint data; return per-type results, importances, sizes."""\n    tr, va, te = host_split(df)\n    bundle = train.fit(tr, va, train.feature_columns(df))\n    shared = len(set(tr.host) & set(te.host))\n    sizes = {"train": len(tr), "calibration": len(va), "test": len(te), "hosts_shared_train_test": shared,\n             "threshold": bundle["threshold"]}\n    return by_type(bundle, te), importances(bundle), sizes\n'),
    ('src/abuselens/cli.py', '"""`abuselens` command line: ingest | marts | enrich | train | monitor | report."""\nfrom __future__ import annotations\n\nimport argparse\nimport logging\nimport sys\n\nfrom . import config, db\nfrom .ingest import runner\n\nALL_SOURCES = ["urlhaus", "openphish", "phishtank", "tranco", "commoncrawl", "sitelinks"]\n\n\ndef cmd_ingest(a):\n    con = db.connect()\n    sources = ALL_SOURCES if a.all else a.sources\n    res = runner.run(con, sources)\n    for k, ok in res.items():\n        print(f"{k:10s} {\'ok\' if ok else \'FAILED (see ingest_log)\'}")\n    return 0 if all(res.values()) else 1\n\n\ndef cmd_marts(a):\n    con = db.connect()\n    for sub in ("staging", "marts"):\n        print(sub, db.run_sql_dir(con, sub))\n    return 0\n\n\ndef cmd_enrich(a):\n    from .enrich.context import enrich_domains\n    con = db.connect()\n    hosts = [r[0] for r in con.execute("""\n        SELECT host FROM (SELECT host FROM stg_malicious_urls UNION ALL SELECT host FROM stg_safe_urls)\n        WHERE host NOT SIMILAR TO \'[0-9.]+\' AND host <> \'\'\n          AND host NOT IN (SELECT domain FROM raw_enrichment)\n        GROUP BY host ORDER BY random() LIMIT ?""", [a.max]).fetchall()]\n    df = enrich_domains(hosts, max_n=a.max)\n    con.register("_e", df)\n    con.execute("INSERT INTO raw_enrichment SELECT * FROM _e")\n    print(f"enriched {len(df)} domains")\n    return 0\n\n\ndef cmd_train(a):\n    from .models import train\n    con = db.connect()\n    db.run_sql_dir(con, "staging")\n    meta = train.train_and_promote(con)\n    m = meta["metrics"]\n    print(f"{meta[\'decision\']} | PR-AUC {m[\'pr_auc\']:.3f} ROC-AUC {m[\'roc_auc\']:.3f} "\n          f"recall {m[\'recall\']:.2%} FPR {m[\'fpr\']:.2%}")\n    return 0\n\n\ndef _monitor(con):\n    from .models import train\n    from .monitoring import drift\n    bundle, _ = train.load(config.MODEL_DIR / "champion")\n    return drift.run(con, bundle)\n\n\ndef cmd_evaluate(a):\n    from .models import evaluate, train\n    con = db.connect()\n    db.run_sql_dir(con, "staging")\n    if a.strict:\n        res, imp, sizes = evaluate.strict_report(train.load_dataset(con))\n        print("STRICT host-disjoint evaluation (fresh model; the saved champion is untouched)")\n        print(f"sizes: {sizes}\\n")\n        print(res.round(4).to_string(index=False))\n        print("\\nTop features by share of total gain:")\n        print(imp.round(4).to_string(index=False))\n        return 0\n    bundle, meta = train.load(config.MODEL_DIR / "champion")\n    _, _, test = train.time_split(train.load_dataset(con))\n    print(f"Held-out test slice: {len(test)} URLs; frozen threshold {bundle[\'threshold\']:.3f}\\n")\n    print(evaluate.by_type(bundle, test).round(4).to_string(index=False))\n    print("\\nTop features by share of total gain:")\n    print(evaluate.importances(bundle).round(4).to_string(index=False))\n    return 0\n\n\ndef cmd_monitor(a):\n    con = db.connect()\n    res = _monitor(con)\n    print(res["decay"].round(3).to_string(index=False))\n    for al in res["alerts"] or ["no alerts"]:\n        print("-", al)\n    return 0\n\n\ndef cmd_report(a):\n    import json\n\n    from .reporting import brief\n    con = db.connect()\n    for sub in ("staging", "marts"):\n        db.run_sql_dir(con, sub)\n    meta_path = config.MODEL_DIR / "champion" / "meta.json"\n    meta = json.loads(meta_path.read_text(encoding="utf-8")) if meta_path.exists() else None\n    try:\n        mon = _monitor(con) if meta else None\n    except Exception:\n        mon = None\n    print(brief.write(brief.build(con, meta, mon)))\n    return 0\n\n\ndef main(argv=None) -> int:\n    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(name)s %(message)s")\n    p = argparse.ArgumentParser(prog="abuselens")\n    sub = p.add_subparsers(dest="cmd", required=True)\n    s = sub.add_parser("ingest")\n    s.add_argument("--all", action="store_true")\n    s.add_argument("--sources", nargs="*", default=[], choices=ALL_SOURCES)\n    s.set_defaults(fn=cmd_ingest)\n    sub.add_parser("marts").set_defaults(fn=cmd_marts)\n    s = sub.add_parser("enrich")\n    s.add_argument("--max", type=int, default=200)\n    s.set_defaults(fn=cmd_enrich)\n    sub.add_parser("train").set_defaults(fn=cmd_train)\n    sub.add_parser("monitor").set_defaults(fn=cmd_monitor)\n    s = sub.add_parser("evaluate")\n    s.add_argument("--strict", action="store_true", help="host-disjoint split with a freshly trained model")\n    s.set_defaults(fn=cmd_evaluate)\n    sub.add_parser("report").set_defaults(fn=cmd_report)\n    a = p.parse_args(argv)\n    return a.fn(a)\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'),
]
for rel, text in FILES:
    (root / rel).write_text(text, encoding="utf-8", newline="")
    print("patched", rel)
